def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    from collections import deque
    from fractions import Fraction

    jump = {a: b for a, b in jumps}
    destination = list(range(n + 1))

    for start in jump:
        cell = start
        while cell in jump:
            cell = jump[cell]
        destination[start] = cell

    transitions = [[] for _ in range(n + 1)]
    reverse = [[] for _ in range(n + 1)]

    for cell in range(n):
        for roll in range(1, m + 1):
            landing = cell + roll
            if landing > n:
                landing = 2 * n - landing
            landing = destination[landing]
            transitions[cell].append(landing)
            reverse[landing].append(cell)

    reachable = [False] * (n + 1)
    reachable[0] = True
    queue = deque([0])
    while queue:
        cell = queue.popleft()
        for nxt in transitions[cell]:
            if not reachable[nxt]:
                reachable[nxt] = True
                queue.append(nxt)

    can_finish = [False] * (n + 1)
    can_finish[n] = True
    queue = deque([n])
    while queue:
        cell = queue.popleft()
        for prev in reverse[cell]:
            if not can_finish[prev]:
                can_finish[prev] = True
                queue.append(prev)

    if any(reachable[cell] and not can_finish[cell] for cell in range(n)):
        return None

    states = [cell for cell in range(n) if reachable[cell]]
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)
    matrix = [[0] * (size + 1) for _ in range(size)]

    for i, cell in enumerate(states):
        matrix[i][i] = m
        matrix[i][size] = m
        for nxt in transitions[cell]:
            if nxt != n:
                matrix[i][index[nxt]] -= 1

    # Fraction-free Gaussian elimination (Bareiss algorithm).
    previous_pivot = 1
    for col in range(size - 1):
        if matrix[col][col] == 0:
            for row in range(col + 1, size):
                if matrix[row][col] != 0:
                    matrix[col], matrix[row] = matrix[row], matrix[col]
                    break
        pivot = matrix[col][col]
        for row in range(col + 1, size):
            factor = matrix[row][col]
            for j in range(col + 1, size + 1):
                matrix[row][j] = (
                    matrix[row][j] * pivot - factor * matrix[col][j]
                ) // previous_pivot
            matrix[row][col] = 0
        previous_pivot = pivot

    solution = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * solution[j]
        solution[i] = value / matrix[i][i]

    answer = solution[index[0]]
    return [answer.numerator, answer.denominator]
